#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; cin >> n;
    int x = 0;
    for(int i=0;i<n;i++){
        long long h; cin >> h;
        x ^= (int)(h % 4);
    }
    cout << (x != 0 ? "First" : "Second") << endl;
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; cin >> n;
    vector<long long> h(n);
    long long mx = 0, x = 0;
    int onesCount = 0;
    for(auto &v : h){ cin >> v; mx = max(mx, v); x ^= v; if(v==1) onesCount++; }
    bool firstWins;
    if(mx <= 1){
        // every pile is 0 or 1: first player wins iff the number of 1-piles is even
        firstWins = (onesCount % 2 == 0);
    } else {
        firstWins = (x != 0);
    }
    cout << (firstWins ? "First" : "Second") << endl;
}
